//! DSP building blocks: analog-prototype biquads, the 2x oversampler and
//! the U 87 electronics non-linearities.
//!
//! Everything runs in `f64`. Filters are designed in the s-domain
//! (see `coeffs.rs`, generated by `tools/model.py`) and discretized
//! here with a bilinear transform pre-warped at each section's own
//! natural frequency, so peaks and corners land where the analog
//! model puts them even close to Nyquist.

use crate::coeffs::Section;
use std::f64::consts::PI;

// ------------------------------------------------------------------ biquad

/// Transposed direct form II biquad.
#[derive(Clone, Copy, Debug)]
pub struct Biquad {
    b0: f64,
    b1: f64,
    b2: f64,
    a1: f64,
    a2: f64,
    z1: f64,
    z2: f64,
}

impl Default for Biquad {
    fn default() -> Self {
        Self { b0: 1.0, b1: 0.0, b2: 0.0, a1: 0.0, a2: 0.0, z1: 0.0, z2: 0.0 }
    }
}

impl Biquad {
    /// Discretize an analog section at `fs` (bilinear, pre-warped).
    /// State is kept so coefficients can change while running.
    pub fn set_analog(&mut self, s: &Section, fs: f64) {
        let [b0, b1, b2, a0, a1, a2] = *s;
        // Natural frequency of the denominator: second order -> sqrt(a2/a0),
        // first order -> a2/a1. Clamp below Nyquist so tan() stays finite.
        let w0 = if a0 != 0.0 && a2 != 0.0 {
            (a2 / a0).sqrt()
        } else if a1 != 0.0 && a2 != 0.0 {
            a2 / a1
        } else {
            2.0 * PI * 1000.0
        };
        let w0 = w0.min(0.45 * 2.0 * PI * fs).max(1e-3);
        let k = w0 / (w0 / (2.0 * fs)).tan();
        let k2 = k * k;
        let nb0 = b0 * k2 + b1 * k + b2;
        let nb1 = 2.0 * (b2 - b0 * k2);
        let nb2 = b0 * k2 - b1 * k + b2;
        let na0 = a0 * k2 + a1 * k + a2;
        let na1 = 2.0 * (a2 - a0 * k2);
        let na2 = a0 * k2 - a1 * k + a2;
        self.b0 = nb0 / na0;
        self.b1 = nb1 / na0;
        self.b2 = nb2 / na0;
        self.a1 = na1 / na0;
        self.a2 = na2 / na0;
    }

    pub fn reset(&mut self) {
        self.z1 = 0.0;
        self.z2 = 0.0;
    }

    #[inline]
    pub fn run(&mut self, x: f64) -> f64 {
        let y = self.b0 * x + self.z1;
        self.z1 = self.b1 * x - self.a1 * y + self.z2;
        self.z2 = self.b2 * x - self.a2 * y;
        y
    }
}

/// Fixed-capacity cascade of biquads (no allocation on the audio thread).
#[derive(Clone, Copy, Debug)]
pub struct Cascade<const N: usize> {
    sections: [Biquad; N],
    len: usize,
}

impl<const N: usize> Default for Cascade<N> {
    fn default() -> Self {
        Self { sections: [Biquad::default(); N], len: 0 }
    }
}

impl<const N: usize> Cascade<N> {
    pub fn set(&mut self, secs: &[Section], fs: f64) {
        debug_assert!(secs.len() <= N);
        self.len = secs.len().min(N);
        for (bq, s) in self.sections.iter_mut().zip(secs) {
            bq.set_analog(s, fs);
        }
    }

    pub fn reset(&mut self) {
        for s in &mut self.sections {
            s.reset();
        }
    }

    #[inline]
    pub fn run(&mut self, mut x: f64) -> f64 {
        for s in &mut self.sections[..self.len] {
            x = s.run(x);
        }
        x
    }
}

// ------------------------------------------------------------- oversampler

/// Half-band FIR length. Odd, so every other tap (except the centre) is 0.
pub const HB_TAPS: usize = 63;
/// Group delay of one half-band pass, in samples at the 2x rate.
const HB_DELAY: usize = (HB_TAPS - 1) / 2;
/// Total latency of up + down sampling, in base-rate samples.
pub const OS_LATENCY: u32 = (2 * HB_DELAY / 2) as u32;

/// Kaiser-windowed half-band low-pass, cutoff at a quarter of the 2x rate
/// (= base-rate Nyquist). Unity DC gain.
pub fn halfband_taps() -> [f64; HB_TAPS] {
    let beta = 8.0;
    let m = (HB_TAPS - 1) as f64;
    let mut h = [0.0; HB_TAPS];
    let mut sum = 0.0;
    for (n, tap) in h.iter_mut().enumerate() {
        let t = n as f64 - m / 2.0;
        let sinc = if t == 0.0 { 0.5 } else { (PI * t / 2.0).sin() / (PI * t) };
        let r = 2.0 * n as f64 / m - 1.0;
        let w = bessel_i0(beta * (1.0 - r * r).max(0.0).sqrt()) / bessel_i0(beta);
        *tap = sinc * w;
        sum += *tap;
    }
    for tap in &mut h {
        *tap /= sum;
    }
    h
}

fn bessel_i0(x: f64) -> f64 {
    let mut sum = 1.0;
    let mut term = 1.0;
    let q = x * x / 4.0;
    for k in 1..50 {
        term *= q / (k * k) as f64;
        sum += term;
        if term < 1e-12 * sum {
            break;
        }
    }
    sum
}

/// Circular FIR delay line, doubled so the dot product reads a contiguous slice.
#[derive(Clone, Copy)]
struct FirLine {
    buf: [f64; 2 * HB_TAPS],
    pos: usize,
}

impl Default for FirLine {
    fn default() -> Self {
        Self { buf: [0.0; 2 * HB_TAPS], pos: 0 }
    }
}

impl FirLine {
    #[inline]
    fn push(&mut self, x: f64) {
        self.pos = if self.pos == 0 { HB_TAPS - 1 } else { self.pos - 1 };
        self.buf[self.pos] = x;
        self.buf[self.pos + HB_TAPS] = x;
    }

    #[inline]
    fn dot(&self, h: &[f64; HB_TAPS]) -> f64 {
        let w = &self.buf[self.pos..self.pos + HB_TAPS];
        let mut acc = 0.0;
        for (a, b) in w.iter().zip(h) {
            acc += a * b;
        }
        acc
    }

    fn reset(&mut self) {
        self.buf = [0.0; 2 * HB_TAPS];
    }
}

#[derive(Clone, Copy, Default)]
pub struct Oversampler {
    up: FirLine,
    down: FirLine,
}

impl Oversampler {
    /// One base-rate sample in -> two 2x-rate samples out.
    #[inline]
    pub fn upsample(&mut self, x: f64, h: &[f64; HB_TAPS]) -> [f64; 2] {
        self.up.push(2.0 * x);
        let a = self.up.dot(h);
        self.up.push(0.0);
        let b = self.up.dot(h);
        [a, b]
    }

    /// Two 2x-rate samples in -> one base-rate sample out.
    #[inline]
    pub fn downsample(&mut self, x: [f64; 2], h: &[f64; HB_TAPS]) -> f64 {
        self.down.push(x[0]);
        self.down.push(x[1]);
        self.down.dot(h)
    }

    pub fn reset(&mut self) {
        self.up.reset();
        self.down.reset();
    }
}

// --------------------------------------------------------- non-linearities
//
// Calibration: an internal amplitude of 1.0 is the U 87's rated maximum
// (117 dB SPL cardioid, 390 mV out, THD 0.5 % per the Neumann data sheet).
// With Drive at 0 dB that point sits at 0 dBFS.

/// JFET common-source stage. Square-law transfer gives mostly 2nd harmonic:
/// y = x + a2 x^2  ->  HD2 = a2 A / 2. a2 = 0.008 => 0.4 % at full scale; the
/// remaining 0.1 % of the 0.5 % budget comes from the output transformer.
/// Past full scale the stage runs out of drain swing (soft clip).
#[derive(Clone, Copy, Default)]
pub struct FetStage {
    dc_x1: f64,
    dc_y1: f64,
    dc_r: f64,
}

const FET_A2: f64 = 0.008;
const FET_KNEE: f64 = 1.0;
const FET_CEIL: f64 = 1.35;

impl FetStage {
    pub fn set_rate(&mut self, fs: f64) {
        // 5 Hz DC blocker removes the offset the square term creates.
        self.dc_r = (-2.0 * PI * 5.0 / fs).exp();
    }

    pub fn reset(&mut self) {
        self.dc_x1 = 0.0;
        self.dc_y1 = 0.0;
    }

    #[inline]
    pub fn run(&mut self, x: f64) -> f64 {
        let v = soft_clip(x + FET_A2 * x * x);
        let y = v - self.dc_x1 + self.dc_r * self.dc_y1;
        self.dc_x1 = v;
        self.dc_y1 = y;
        y
    }
}

#[inline]
fn soft_clip(x: f64) -> f64 {
    let a = x.abs();
    if a <= FET_KNEE {
        x
    } else {
        let room = FET_CEIL - FET_KNEE;
        (FET_KNEE + room * ((a - FET_KNEE) / room).tanh()).copysign(x)
    }
}

/// Output transformer core: magnetizing current is a cubic function of
/// flux (phi = integral of voltage); flowing through the source impedance it
/// subtracts c3 * phi^3. Because phi ~ V / f, distortion rises steeply toward
/// low frequencies (HD3 ~ 1 / f^3), which is the characteristic "weight" of a
/// transformer-coupled mic on low notes and practically nothing above 200 Hz.
#[derive(Clone, Copy, Default)]
pub struct Transformer {
    phi: f64,
    a: f64,
    g: f64,
}

/// Flux normalization: |phi| = |x| at this frequency.
const XF_F_REF: f64 = 30.0;
/// Leak keeps the integrator DC-stable.
const XF_F_LEAK: f64 = 3.0;
/// HD3 = c3 / 4 at full scale and XF_F_REF => 1 % at 30 Hz, ~0.004 % at 200 Hz.
const XF_C3: f64 = 0.04;
const XF_PHI_MAX: f64 = 1.5;

impl Transformer {
    pub fn set_rate(&mut self, fs: f64) {
        self.a = (-2.0 * PI * XF_F_LEAK / fs).exp();
        self.g = (1.0 - self.a) * XF_F_REF / XF_F_LEAK;
    }

    pub fn reset(&mut self) {
        self.phi = 0.0;
    }

    #[inline]
    pub fn run(&mut self, x: f64) -> f64 {
        self.phi = self.a * self.phi + self.g * x;
        // Core saturation: flux can't grow without bound.
        let p = XF_PHI_MAX * (self.phi / XF_PHI_MAX).tanh();
        x - XF_C3 * p * p * p
    }
}

// ---------------------------------------------------------------- helpers

/// First-order proximity-effect transfer for a first-order gradient mic
/// at distance r from a point source:
///     H(s) = 1 + g c / (s r) = (s + a) / s,   a = g c / r
/// with g the gradient fraction of the pattern (omni 0, cardioid 0.5,
/// figure-8 1). Re-mapping SM58 at r_s to U 87 at r_u is the ratio
///     (s + a_u) / (s + a_s)
/// (the common 1/s cancels), a first-order shelf.
pub fn proximity_section(g_src: f64, r_src: f64, g_dst: f64, r_dst: f64) -> Section {
    const C: f64 = 343.0;
    let a_s = g_src * C / r_src;
    let a_u = g_dst * C / r_dst;
    // Keep a pole: if the source were pure pressure (a_s = 0) fall back to a
    // sub-audio pole so the section stays stable.
    let a_s = a_s.max(2.0 * PI * 2.0);
    [0.0, 1.0, a_u, 0.0, 1.0, a_s]
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Steady-state gain in dB, measured by correlating with the input
    /// sinusoid (a sample-peak reading under-reads near Nyquist).
    fn mag_db(cascade: &mut impl FnMut(f64) -> f64, f: f64, fs: f64) -> f64 {
        let n = (fs * 0.5) as usize;
        let (mut re, mut im, mut m) = (0.0, 0.0, 0usize);
        for i in 0..n {
            let ph = 2.0 * PI * f * i as f64 / fs;
            let y = cascade(ph.sin());
            if i > n / 2 {
                re += y * ph.sin();
                im += y * ph.cos();
                m += 1;
            }
        }
        20.0 * (2.0 * (re * re + im * im).sqrt() / m as f64).log10()
    }

    #[test]
    fn bilinear_peak_lands_on_frequency() {
        // RBJ analog peak at 10 kHz, +6 dB, Q 2
        let w = 2.0 * PI * 10_000.0;
        let a = 10f64.powf(6.0 / 40.0);
        let s: Section = [1.0, a * w / 2.0, w * w, 1.0, w / (a * 2.0), w * w];
        let mut bq = Biquad::default();
        bq.set_analog(&s, 88_200.0);
        let g = mag_db(&mut |x| bq.run(x), 10_000.0, 88_200.0);
        assert!((g - 6.0).abs() < 0.1, "peak gain {g}");
    }

    #[test]
    fn oversampler_is_transparent_in_band() {
        let h = halfband_taps();
        let fs = 48_000.0;
        for (f, tol) in [(1000.0, 0.01), (18_000.0, 0.1), (20_000.0, 0.5)] {
            let mut os = Oversampler::default();
            let g = mag_db(
                &mut |x| {
                    let u = os.upsample(x, &h);
                    os.downsample(u, &h)
                },
                f,
                fs,
            );
            eprintln!("oversampler {f} Hz: {g:+.3} dB");
            assert!(g.abs() < tol, "{f} Hz: {g} dB");
        }
    }

    #[test]
    fn transformer_distortion_is_low_frequency() {
        // THD at 30 Hz full scale ~1 %, at 1 kHz negligible.
        let fs = 96_000.0;
        let thd = |f: f64| {
            let mut t = Transformer::default();
            t.set_rate(fs);
            let n = (fs * 2.0) as usize;
            let mut out = vec![0.0; n];
            for (i, o) in out.iter_mut().enumerate() {
                *o = t.run((2.0 * PI * f * i as f64 / fs).sin());
            }
            // 3rd harmonic amplitude via single-bin DFT over the last second
            let tail = &out[n / 2..];
            let bin = |k: f64| {
                let (mut re, mut im) = (0.0, 0.0);
                for (i, v) in tail.iter().enumerate() {
                    let p = 2.0 * PI * k * f * i as f64 / fs;
                    re += v * p.cos();
                    im += v * p.sin();
                }
                (re * re + im * im).sqrt()
            };
            bin(3.0) / bin(1.0)
        };
        let lo = thd(30.0);
        let hi = thd(1000.0);
        assert!(lo > 0.005 && lo < 0.02, "HD3 @30 Hz = {lo}");
        assert!(hi < 1e-5, "HD3 @1 kHz = {hi}");
    }
}
